document.querySelector('.transport').append(Object.assign(document.createElement('label'),{className:'preview-speed-control',innerHTML:'Preview <select id="previewPlaybackSpeed" aria-label="Preview playback speed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option><option value="4">4×</option></select>'}));
function previewSpeed(){return project.previewSpeed||1}
playTimelineAudio=async function(at){stopTimelineAudio();const ac=new AudioContext(),speed=previewSpeed();previewAudioContext=ac;await ac.resume();if(previewAudioContext!==ac||!playing){ac.close().catch(()=>{});return}for(const c of tracks()){const buffer=audioBuffers.get(c.id);if(!buffer||audioEnd(c)<=at||c.start>=totalDuration())continue;const rate=c.rate||1,source=ac.createBufferSource(),gain=ac.createGain();source.buffer=buffer;source.playbackRate.value=rate*speed;source.connect(gain).connect(ac.destination);const skip=Math.max(0,at-c.start),length=Math.min(c.duration-skip,(buffer.duration-c.offset-skip*rate)/rate,totalDuration()-Math.max(at,c.start));if(length<=0)continue;const when=ac.currentTime+Math.max(0,c.start-at)/speed,count=Math.max(2,Math.min(200000,Math.ceil(length*100)+1)),values=new Float32Array(count);for(let i=0;i<count;i++)values[i]=envelopeAt(c,skip+length*i/(count-1));gain.gain.setValueCurveAtTime(values,when,length/speed);source.start(when,c.offset+skip*rate,length*rate);previewSources.push(source)}};
play=function(){if(playing)return stop();if(globalTime()>=totalDuration())seekGlobal(0);playing=true;$('play').textContent='Ⅱ';const at=globalTime(),start=performance.now(),speed=previewSpeed();playTimelineAudio(at);function tick(now){let t=Math.min(totalDuration(),at+(now-start)/1000*speed),i=0;while(i<project.scenes.length-1&&t>=project.scenes[i].duration){t-=project.scenes[i].duration;i++}if(sceneIndex!==i){sceneIndex=i;time=t;selected=null;render()}else{time=t;draw()}if(at+(now-start)/1000*speed<totalDuration())raf=requestAnimationFrame(tick);else{stop();render()}}raf=requestAnimationFrame(tick)};$('play').onclick=play;
$('previewPlaybackSpeed').onchange=e=>{const resume=playing;stop();project.previewSpeed=+e.target.value;save();if(resume)play()};const syncBeforePreviewSpeed=syncVideoMedia;syncVideoMedia=function(){syncBeforePreviewSpeed();if(playing)for(const{video}of videoMedia.values())if(!video.paused)video.playbackRate=clamp(video.playbackRate*previewSpeed(),.0625,16)};
function retimeLayerAnimation(o,factor){if(!o||o.locked||!Number.isFinite(factor)||factor<.25||factor>4)throw Error('Choose an unlocked layer and a timing factor between 0.25 and 4.');const si=sceneIndex,start=clipStart(o),end=clipEnd(o),newEnd=start+(end-start)/factor;if(newEnd>current().duration+.001||newEnd-start<.1)throw Error('Extend this scene before slowing the layer, or choose a less extreme speed.');const copy=structuredClone(project),s=copy.scenes[si],actor=s.objects.find(a=>a.id===o.id),map=t=>t<start?t:start+(t-start)/factor;for(const k of actor.keys)if(k.t>=start&&k.t<=end+.001)k.t=map(k.t);for(const track of Object.values(actor.bodyAnimation||{}))for(const k of track.keys)if(k.t>=start&&k.t<=end+.001)k.t=map(k.t);for(const keys of Object.values(actor.objectAnimation||{}))for(const k of keys)if(k.t>=start&&k.t<=end+.001)k.t=map(k.t);for(const list of [actor.expressionKeys,actor.viewKeys,actor.handGestureKeys])for(const k of list||[])if(k.t>=start&&k.t<=end+.001)k.t=map(k.t);for(const block of actor.actionBlocks||[]){block.start=map(block.start);block.duration/=factor;for(const field of ['blendIn','blendOut'])if(block[field]!==undefined)block[field]=Math.min(2,block[field]/factor)}if(actor.motionPath){actor.motionPath.start=map(actor.motionPath.start);actor.motionPath.end=map(actor.motionPath.end)}for(const pin of actor.footPins||[]){pin.start=map(pin.start);pin.end=map(pin.end)}for(const cue of actor.wordAnimation?.words||[]){cue.start=map(cue.start);cue.duration/=factor}if(actor.textFollow)actor.textFollow.start=map(actor.textFollow.start);if(actor.textDuration)actor.textDuration=clamp(actor.textDuration/factor,.1,30);if(actor.explainerAsset)actor.explainerAsset.speed=clamp((actor.explainerAsset.speed||1)*factor,.1,4);if(actor.type==='video'){actor.speed=(actor.speed||1)*factor;if(actor.speed<.25||actor.speed>4)throw Error('Video speed must stay between 0.25 and 4.')}actor.out=newEnd;const audioIds=new Set(storyLines(s).filter(l=>l.speakerId===actor.id).map(l=>l.audioId));if(actor.speechTrackId)audioIds.add(actor.speechTrackId);let offset=0;for(let i=0;i<si;i++)offset+=copy.scenes[i].duration;for(const c of copy.audioClips||[])if(c.videoId===actor.id||audioIds.has(c.id)){c.start=offset+map(c.start-offset);c.duration/=factor;c.rate=(c.rate||1)*factor;if(c.rate<.25||c.rate>4)throw Error('Linked audio speed must stay between 0.25 and 4.');for(const field of ['fadeIn','fadeOut'])if(c[field]!==undefined)c[field]/=factor}for(const l of storyLines(s))if(l.speakerId===actor.id){l.start=map(l.start);l.duration/=factor;l.pause/=factor;l.overlap/=factor;if(l.manualStart!==null&&l.manualStart!==undefined)l.manualStart=map(l.manualStart)}for(const event of s.propInteractions||[])if([event.actorId,event.propId,event.otherId].includes(actor.id)){event.start=map(event.start);event.duration/=factor}if(!valid(copy))throw Error('This timing would move linked content outside valid clip or scene limits.');stop();project.scenes[si]=s;project.audioClips=copy.audioClips;time=clamp(map(time),clipStart(actor),newEnd);selectLayers([actor.id]);save();render();return actor}
function setRecordedVoiceSpeed(c,rate){if(!c||c.locked||!Number.isFinite(rate)||rate<.25||rate>4)throw Error('Choose an unlocked voice and a speed from 0.25 to 4.');if(c.videoId)throw Error('Change the video speed to keep its original sound linked.');const duration=c.duration*(c.rate||1)/rate;if(c.start+duration>totalDuration()+.001)throw Error('Extend the project before slowing this voice.');stop();const old=c.duration;c.rate=rate;c.duration=duration;for(const field of ['fadeIn','fadeOut'])if(c[field]!==undefined)c[field]*=duration/old;for(const s of project.scenes)for(const line of storyLines(s))if(line.audioId===c.id){line.duration=duration;s.dialogueArranged=false}duckActivityCache=null;save();render()}
function setWalkTravelSpeed(o,block,speed){if(o.locked||block.type!=='walk'||!Number.isFinite(speed)||speed<1||speed>2000)throw Error('Choose a walking speed between 1 and 2,000 canvas units per second.');const duration=Math.hypot(block.to.x-block.from.x,block.to.y-block.from.y)/speed;if(duration<.1||block.start+duration>clipEnd(o)+.001)throw Error('Extend the character clip to fit this walking speed.');block.duration=duration;save();render();return duration}
const controlsBeforeSpeeds=renderControls;renderControls=function(){controlsBeforeSpeeds();const o=object();if(!o)return;const timing=document.createElement('details');timing.innerHTML='<summary>Animation speed</summary><label>Timing factor<select id="layerAnimationSpeed"><option value="0.25">0.25× slower</option><option value="0.5">0.5× slower</option><option value="1" selected>1× unchanged</option><option value="1.5">1.5× faster</option><option value="2">2× faster</option><option value="4">4× faster</option></select></label><button id="applyLayerAnimationSpeed">Retime this layer</button><p class="note">Changes its animation keys, actions and linked voice timing together. Scene length stays fixed. Preview speed above the timeline only changes how you review the project.</p>';$('controls').append(timing);$('applyLayerAnimationSpeed').disabled=!!o.locked;$('applyLayerAnimationSpeed').onclick=()=>{try{retimeLayerAnimation(o,+$('layerAnimationSpeed').value)}catch(e){toast(e.message)}};const block=o.actionBlocks?.find(b=>b.id===selectedActionId);if(block?.type==='walk'&&$('selectedActionControls')){const label=document.createElement('label');label.textContent='Travel speed';const input=document.createElement('input');input.id='walkUnitsPerSecond';input.type='number';input.min=1;input.max=2000;input.step=5;input.value=+(Math.hypot(block.to.x-block.from.x,block.to.y-block.from.y)/block.duration).toFixed(1);input.disabled=!!o.locked;input.onchange=()=>{try{setWalkTravelSpeed(o,block,+input.value)}catch(e){toast(e.message);input.value=+(Math.hypot(block.to.x-block.from.x,block.to.y-block.from.y)/block.duration).toFixed(1)}};label.append(input);const ease=storySelect([['smooth','Ease in / out'],['linear','Constant speed']],block.travelEase||'smooth',value=>{if(o.locked)return;block.travelEase=value;save();draw()},'Walk travel easing');$('selectedActionControls').append(label,ease)}};
const clipBeforeVoiceSpeed=renderClipSettings;renderClipSettings=function(){clipBeforeVoiceSpeed();const c=tracks().find(c=>c.id===selectedAudio);if(!c||c.videoId)return;const label=document.createElement('label');label.textContent='Audio / lip-sync speed';const input=storyNumber(c.rate||1,.25,4,value=>{try{setRecordedVoiceSpeed(c,value)}catch(e){toast(e.message)}},'Recorded audio and lip-sync speed');input.disabled=!!c.locked;label.append(input);$('clipSettings').append(label)};
const extrasBeforeSpeed=renderExtras;renderExtras=function(){extrasBeforeSpeed();$('previewPlaybackSpeed').value=String(previewSpeed())};
const validBeforeSpeeds=valid;valid=function(p){return validBeforeSpeeds(p)&&(p.previewSpeed===undefined||[.25,.5,1,1.5,2,4].includes(p.previewSpeed))&&p.scenes.every(s=>s.objects.every(o=>(o.actionBlocks||[]).every(b=>b.travelEase===undefined||['smooth','linear'].includes(b.travelEase))))};
